contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount, address spender) public {
        require(amount < 2**200);
        c.approve(spender, amount); if (__ESBMC_reverted()) return;
        c.correctRState(); if (__ESBMC_reverted()) return;
        uint32 r = c._RState_(); if (__ESBMC_reverted()) return;
        uint112 baseReserve = c._BASE_RESERVE_(); if (__ESBMC_reverted()) return;
        uint112 quoteReserve = c._QUOTE_RESERVE_(); if (__ESBMC_reverted()) return;
        uint112 baseTarget = c._BASE_TARGET_(); if (__ESBMC_reverted()) return;
        uint112 quoteTarget = c._QUOTE_TARGET_(); if (__ESBMC_reverted()) return;
        assert(
            !(r == uint32(2) && baseReserve < baseTarget) &&
            !(r == uint32(1) && quoteReserve < quoteTarget)
        );
    }
    receive() external payable {}
}

