// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 amount, address spender) internal {
        vm.assume(amount < 2**200);
        try c.approve(spender, amount) {} catch { return; }
        try c.correctRState() {} catch { return; }
        uint32 r;
        try c._RState_() returns (uint32 __r) { r = __r; } catch { return; }
        uint112 baseReserve;
        try c._BASE_RESERVE_() returns (uint112 __r) { baseReserve = __r; } catch { return; }
        uint112 quoteReserve;
        try c._QUOTE_RESERVE_() returns (uint112 __r) { quoteReserve = __r; } catch { return; }
        uint112 baseTarget;
        try c._BASE_TARGET_() returns (uint112 __r) { baseTarget = __r; } catch { return; }
        uint112 quoteTarget;
        try c._QUOTE_TARGET_() returns (uint112 __r) { quoteTarget = __r; } catch { return; }
        assertTrue(!(r == uint32(2) && baseReserve < baseTarget) &&
            !(r == uint32(1) && quoteReserve < quoteTarget));
    }

    function testFuzz_run(uint256 amount, address spender) public {
        vm.assume(spender.code.length == 0 && uint160(spender) > 0xffff && spender != address(this) && spender != address(c) && spender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && spender != 0x000000000000000000636F6e736F6c652e6c6f67 && spender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && spender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, spender);
    }

    receive() external payable {}
}
